where $C$ is a (nonempty) closed and convex subset of $\HH$ and 
$F:C\to \HH$ is assumed to be (point-to-point) \emph{monotone}
and continuously differentiable with a $L$-Lipschitz continuous derivative, i.e., $F$ and $F'$ satisfy the following conditions for all
$x,y\in C$:
%
\begin{align}\lab{eq:mon.lip}
\begin{aligned}
%
& \inner{F(x) - F(y)}{x - y}\geq 0,\\[2mm]
& \norm{F'(x) - F'(y)}\leq L\norm{x-y}.
 %
\end{aligned}
\end{align}

\begin{algorithm}[H]
\lab{alg:rHPE}
 \caption{A special instance of the large-step under-relaxed HPE method for \eqref{eq:probim}}
%
\lab{alg_gen}
%
\SetAlgoLined
\KwInput{$x_0\in \HH$, $0<\tau<1$, $0\leq \sigma <1$, $\eta>0$ and $N\in \N\cup \{\infty\}$}
 \For{$k = 1,2,\dots, N$}{
  Choose $\lambda_k>0$ and find $y_k\in \HH$ and $\nu_k\in N_C(y_k)$ such that\\
  %
  \begin{align}
  %
  \lab{eq:rel.al1}
   &\left\|\lambda_k \left(F(y_k) + \nu_k\right) + y_k - x_{k-1}\right\|\leq \sigma\norm{y_k - x_{k-1}}\\[2mm]
   \lab{eq:lar.ste}
   &\lambda_k\norm{y_k - x_{k-1}}\geq \eta
  %
  \end{align}
  %
  Set
  %
  \begin{align}\lab{eq:ext.al1}
  %
   x_k = x_{k-1} - \tau\lambda_k \left(F(y_k) + \nu_k\right)
  %
  \end{align}
  }
\end{algorithm}

The \emph{ergodic sequences} associated to the sequences generated by Algorithm \ref{alg:rHPE} are defined as 
follows (see, e.g., \cite{mon.sva-hpe.siam10}):

\begin{align}\lab{eq:def.erg1}
%
& y_k^a = \dfrac{1}{\sum_{i=1}^k\,\lambda_i}\,\sum_{i=1}^k\,\lambda_i  y_i,\\[2mm]
%
\lab{eq:def.erg2}
& v_k^a = \dfrac{1}{\sum_{i=1}^k\,\lambda_i}\,\sum_{i=1}^k\,\lambda_i  \left(F(y_i) + \nu_i\right),\\[2mm]
%
\lab{eq:def.erg3}
& \varepsilon_k^a = \dfrac{1}{\sum_{i=1}^k\,\lambda_i}\,\sum_{i=1}^k\,\lambda_i \inner{y_i - y_k^a}{F(y_i) + \nu_i- v_k^a}.
%
\end{align}

\bdefi[$\hat\sigma$-approximate solution of \eqref{eq:farias}]
 \lab{def:app_sol}
%
For $y_{k-1}\in C$, $x_{k-1}\in \HH$ and $\lambda_k>0$, a pair $(y_k,\nu_k)\in \HH\times \HH$ is said to be a 
$\hat\sigma$-approximate solution of \eqref{eq:farias} 
if $\hat\sigma\in [0,1/2)$ and
%
\begin{align}\lab{eq:app_sol}
\begin{aligned}
%
\begin{cases}
%
\nu_k\in N_C(y_k),\\[3mm]
%
\norm{\lambda_k\left(F_{y_{k-1}}(y_k) + \nu_k\right) + y_k - x_{k-1}} \leq \hat\sigma\norm{y_k - y_{k-1}}.
%
\end{cases}
%
\end{aligned}
\end{align}
%
\edefi

Let 
\begin{align}
  \lab{eq:hsigma}
  0 \leq \hat\sigma <1/2
\end{align}
be the parameter of approximate solution of \eqref{eq:farias}, as
in Definition~\ref{def:app_sol}.
%
This $\hat\sigma$ can be regarded as the inexactness of an (inexact) oracle which
solves approximately the strongly monotone linear VIP~\eqref{eq:farias}.


Before stating the main algorithm, 
choose and define the parameters $\theta$, $\hat\theta$, $\eta$, $\tau$
as follows:
% consider
\begin{align}\lab{eq:def.hth}
  0 < \theta<(1-\hat\sigma)(1-2\hat\sigma),
  \quad 
  \hat\theta & := \theta\left(\dfrac{\hat\sigma}{1-\hat\sigma}
+ \dfrac{\theta}{(1-\hat\sigma)^2}\right)
\end{align}
and 
\begin{align}\lab{eq:def.tau.alg}
%
    \eta & > \dfrac{2\hat\theta}{L},
  \quad \tau  := \dfrac{2 \left(\theta - \hat\theta\right)}
{2\theta + \dfrac{\eta L}{2} + \sqrt{\left(2\theta + \dfrac{\eta L}{2}\right)^2 
- 4\theta\left(\theta - \hat\theta\right)}}.
%
\end{align}

\begin{algorithm}[H]
%
 \caption{A relative-error inexact proximal-Newton algorithm for solving \eqref{eq:probm}}
%
\lab{alg:main}
%
\SetAlgoLined
\KwInput{$x_0\in C$,$\;y_0:=x_0$, $\nu_0 := 0$, the scalars 
 $\hat\sigma$, $\theta$, $\;\hat\theta$ $\eta$, $\tau$
 as in \eqref{eq:hsigma}--\eqref{eq:def.tau.alg}
and $\lambda_1>0$ such that $\lambda_1^2\norm{F(y_0)}\leq 2\theta/L$
%
}
 \For{$k=1,2,\dots$}{
 %
 \If{$F(y_{k-1})+\nu_{k-1}=0$}
 	{\Return $y_{k-1}$\\\lab{eq:return}}
%
 \eIf{$\dfrac{\lambda_k L}{2}\norm{\lambda_k \left(F(y_{k-1}) + \nu_{k-1}\right) + y_{k-1} - x_{k-1}}\leq 
  \hat\theta$}
  {$y_k = y_{k-1}$\\ \lab{eq:n.cond}
   $\nu_k =\nu_{k-1}$ \\ \lab{eq:n.cond02}}
  {Find a $\hat\sigma$-approximate solution $(y_k,\nu_k)$ of \eqref{eq:farias} (in the sense of
   Definition \ref{def:app_sol}), i.e., find $(y_k,\nu_k)$ satisfying
   %
   \begin{align}\lab{eq:err.cri}
    %
    \begin{cases}
    %
   \nu_k\in N_C(y_k),\\[3mm]
   %
   \norm{\lambda_k\left(F_{y_{k-1}}(y_k) + \nu_k\right) + y_k - x_{k-1}} \leq \hat\sigma\norm{y_k - y_{k-1}}
   %
   \end{cases}
  %
  \end{align} \lab{eq:do.newton}}
  %
 %  
   \eIf{$\lambda_k\norm{y_k - x_{k-1}}\geq \eta$}
      {
      \vspace{0.2cm}
      $x_{k} = x_{k-1} -\tau\lambda_k \left(F(y_k) + \nu_k\right)$\\[2mm]\lab{eq:ext.step}
      \vspace{0.1cm}
      $\lambda_{k+1} = (1 - \tau)\lambda_k$\\[3mm]\lab{eq:red.lam}
      }
     {$x_k = x_{k-1}$\\[2mm]\lab{eq:null.step}
     $\lambda_{k+1} = \dfrac{\lambda_k}{1 - \tau}$\\\lab{eq:inc.lam}
     }
  %
  }
\end{algorithm}

For every $j\geq 1$, define
%
\begin{align}
  \lab{eq:def.ab}
  \begin{aligned}
    A_j & =\left\{1\leq k \leq j\;|\;\; \text{$\lambda_k\norm{y_k - x_{k-1}}\geq \eta$\; holds at iteration $k$}\right\},
	  & a_j =\# A_j\,,\\
    B_j & =\{1\leq k\leq j\;|\;\; 
   \text{$\lambda_k\norm{y_k - x_{k-1}} < \eta$\; holds at iteration $k$}\},
    & b_j =\# B_j\,,
  \end{aligned}
\end{align}
%
\begin{align}
 \lab{eq:uni.ab}
 A =\bigcup_{j=1}^\infty A_j\;\;\mbox{and}\;\; B =\bigcup_{j=1}^\infty B_j.
\end{align}
%
We also define
%
\begin{align}
\lab{eq:s70}
  K=\set{k\geq 1\;|\; k\leq \# A},\quad
  i_0=0,\quad i_k=\text{$k$-th element of }A,
\end{align}
%
and note that 
%
\begin{align}
 \lab{eq:car.a}
  i_0<i_1<i_2<\cdots,\qquad A=\set{i_k\;|\; k\in K}.
\end{align}

\begin{theorem} 
 \lab{th:rhpe}
%
Consider the sequences evolved by \emph{Algorithm \ref{alg:rHPE}} and the ergodic sequences as in \eqref{eq:def.erg1}--\eqref{eq:def.erg3}. Let also $d_0$ denote the distance of $x_0$ to the solution set $(F + N_C)^{-1}(0)\neq \emptyset$ of \eqref{eq:probim}. The following hold for all $1\leq k\leq N$:
%
\begin{itemize}
%
\item[\emph{(a)}] There exists $1\leq j\leq k$ such that $\nu_j\in N_C(y_j)$ and
%
\begin{align*}
%
\norm{F(y_j) + \nu_j}\leq \dfrac{d_0^2}{\tau \eta (1-\sigma)\,k}\,.
%
\end{align*}
%
\item[\emph{(b)}] $v_k^a\in (F + N_C)^{\varepsilon_k^a}(y_k^a)$ and
%
\begin{align*}
%
\norm{v_k^a}&\leq \dfrac{2d_0^2}{\tau^{3/2}\eta\sqrt{1-\sigma^2}\,k^{3/2}}\,,\\[3mm]
%
\varepsilon_k^a&\leq \dfrac{2d_0^3}{\tau^{3/2}\eta(1-\sigma^2)\,k^{3/2}}.
%
\end{align*}
%
\end{itemize}
%
\end{theorem}

\begin{proposition}\lab{prop:stepb}
%
Consider the sequences evolved by \emph{Algorithm \ref{alg:main}}. Then, for all $k\geq 1$,
%
\begin{align*}
%
\norm{y_k - y_{k-1}}\leq \dfrac{1}{1-\hat\sigma}\norm{\lambda_k \left(F(y_{k-1})+\nu_{k-1}\right) + y_{k-1} - x_{k-1}}.
%
\end{align*}
%
\end{proposition}

Note also that using \eqref{eq:def.ek} and the inequality in \eqref{eq:err.cri} we also find
%
\begin{align}\lab{eq:lego3}
%
\norm{e_k}\leq \hat\sigma \norm{y_k - y_{k-1}}
\qquad \forall k\geq 1.
%
\end{align}

As a consequence, from Proposition \ref{prop:stepb},
%
\begin{align*}
%
\norm{\lambda_k \left(F(y_k) + \nu_k\right) + y_k - x_{k-1}} &\leq 
\dfrac{\hat\sigma}{1-\hat\sigma}\norm{\lambda_k \left(F(y_{k-1}) + \nu_{k-1}\right) + y_{k-1} - x_{k-1}}\\[2mm]
& \hspace{2cm}+\dfrac{1}{(1-\hat\sigma)^2}\dfrac{\lambda_k L}{2}
\norm{\lambda_k \left(F(y_{k-1}) + \nu_{k-1}\right) + y_{k-1} - x_{k-1}}^2.
%
\end{align*}

\brema \lab{rm:rm}
%
\emph{
We claim that
if $(x_k)$ is generated by Algorithm \ref{alg:main} then
%
\begin{align}
\lab{eq:ixk}
 x_{i_k-1}=x_{i_{k-1}}\qquad \forall k\in K,
\end{align}
%
where $K$ is as in \eqref{eq:s70} -- see also \eqref{eq:car.a}.

\bprop \lab{prop:special}
%
Consider the sequences evolved by \emph{Algorithm \ref{alg:main}} and let the set $K$ be as in \eqref{eq:s70} 
and \eqref{eq:car.a}.
%
Then, for all $k\in K$,
%
\begin{align}
%\begin{aligned}
  %
  \lab{eq:stick00}
  &\nu_{i_k}\in N_C(y_{i_k}),\\[2mm]
  \lab{eq:stick01}
   &\left\|\lambda_{i_k} \left(F(y_{i_k}) + \nu_{i_k}\right) + y_{i_k} - x_{i_{k-1}}\right\|\leq \sigma\norm{y_{i_k} - x_{i_{k-1}}},\\[2mm]
   %
   \lab{eq:stick02}
   &\lambda_{i_k}\norm{y_{i_k} - x_{i_{k-1}}}\geq \eta,\\[2mm]
   %
   \lab{eq:stick03}
   & x_{i_k} = x_{i_{k-1}} - \tau\lambda_{i_k} \left(F(y_{i_k}) + \nu_{i_k}\right),
  %
  %\end{aligned}
  \end{align}
  %
  where
 %
 \begin{align}\lab{eq:def.sigma}
 %
 \sigma:=\dfrac{2\hat\theta}{\eta L}<1.
%
 \end{align}
 %
 As a consequence, the sequences $(x_{i_k})_{k\in K}$, $(y_{i_k})_{k\in K}$ and $(\lambda_{i_k})_{k\in K}$ are generated
 by \emph{Algorithm \ref{alg:rHPE}} \emph{(}with $N=\# A$\emph{)} for solving \eqref{eq:probm}.
%
\eprop

\begin{lemma} \lab{lm:geo}
%
Let $(\lambda_k)$ be generated by \emph{Algorithm \ref{alg:main}} and let $(a_k)$ and $(b_k)$ be as in \eqref{eq:def.ab}.
Then, for all $k\geq 1$,
%
\begin{align}
%
\lambda_{k+1} = (1 - \tau)^{a_{k} - b_{k}}\lambda_1.
%
\end{align}
%
\end{lemma}

\begin{lemma}
 \lab{lm:lip}
 %
 Let $F:\HH\to \HH$ be a continuously differentiable mapping
  with a $L$-Lipschitz continuous derivative $F'(\cdot)$, i.e., let $F$ be such that there exits $L\geq 0$ satisfying
%
\begin{align}
 \lab{eq:lip.app}
 \norm{F'(x) - F'(y)}\leq L\norm{x - y}\qquad  \forall x,y \in \HH.
\end{align}
%
Then,
%
  \[
   \norm{F(x) - F_y(x)}\leq \dfrac{L}{2}\norm{x - y}^2 \qquad \forall x,y\in \HH,
  \]
  %
  where $F_y(x)$ is as in \eqref{eq:def.lin}.
  %
\end{lemma}
